  const chokepoints=[
    ["SUEZ","Canal de Suez",12],["PANAMA","Canal de Panamá",6],["MALACCA","Estrecho de Malaca",24],["HORMUZ","Estrecho de Ormuz",19],["BAB_EL_MANDEB","Bab el-Mandeb",10],["GIBRALTAR","Gibraltar",9],["BOSPHORUS","Bósforo",5],["ENGLISH_CHANNEL","Canal de la Mancha",11],["CAPE_GOOD_HOPE","Cabo de Buena Esperanza",8],["BLACK_SEA","Mar Negro",7],["RED_SEA","Mar Rojo",10],["SOUTH_CHINA_SEA","Mar de China Meridional",22]
  ].map(([id,name,worldFlow])=>({id,name,worldFlow,status:"open",capacity:100,congestion:20,warRisk:5,insurancePremium:1,delayDays:0}));
  const institutionKeys=["headOfState","government","parliament","senate","judiciary","constitutionalCourt","centralBank","armedForces","police","intelligenceServices","regionalGovernments","municipalities","tradeUnions","employerAssociations","churches","media","lobbies","civilOrganizations"];
