  const organizationDefs=[
    ["UN","ONU","security",true],["UNSC","Consejo de Seguridad","security",true],["NATO","OTAN","defense",true],["EU","Unión Europea","integration",true],["AU","Unión Africana","regional",true],["ASEAN","ASEAN","regional",true],["MERCOSUR","Mercosur","trade",true],["OPEC","OPEP","energy",true],["G7","G7","coordination",false],["G20","G20","coordination",false],["IMF","FMI","finance",true],["WORLD_BANK","Banco Mundial","finance",true],["WTO","OMC","trade",true],["BRICS","BRICS","coordination",false],["ARAB_LEAGUE","Liga Árabe","regional",true]
  ].map(([id,name,type,binding])=>({id,name,type,binding,members:[],votes:[],funds:100,quota:1,obligations:[],sanctions:[],resolutions:[]}));
  const influenceChannels=["aid","investment","infrastructure","armsSales","culture","education","media","debt","technology","militaryBases","intelligence"];
  const financeInstruments=["sovereignBonds","corporateBonds","commodities","currencies","nationalIndices","sovereignFunds","pensionFunds","simulatedETFs","energyFutures","creditDefaultSwaps","interbank","shortSelling"];
  const cityNames={ESP:["Madrid","Barcelona","Valencia","Sevilla","Bilbao"],USA:["Washington D. C.","New York","Los Angeles","Chicago","Houston"],MEX:["Ciudad de México","Monterrey","Guadalajara"],COL:["Bogotá","Medellín","Cali"],MAR:["Rabat","Casablanca","Tánger"],CHN:["Pekín","Shanghái","Shenzhen"],IND:["Nueva Delhi","Mumbai","Bengaluru"],BRA:["Brasilia","São Paulo","Río de Janeiro"]};

  const scaleFor=(c,p)=>Math.max(.01,c.economy.gdp*p.weight);
  function market(c,p,i){
    const base=scaleFor(c,p),resource=(c.systems.energy+c.systems.industry+c.systems.food+c.systems.technology)/400;
    const specialization=(p.id==="grains"||p.id==="meat"||p.id==="fertilizers")?c.systems.food/70:(p.id==="electricity"||["oil","gas","coal","uranium"].includes(p.id))?c.systems.energy/70:(p.id==="semiconductors"||p.id==="digitalServices")?c.systems.technology/70:c.systems.industry/70;
    const production=round(base*clamp(.45+resource*.28+specialization*.32+(i%5)*.025,.25,1.7));
    const intermediateConsumption=round(base*.42),householdConsumption=round(base*.36),publicConsumption=round(base*.12),demand=round(intermediateConsumption+householdConsumption+publicConsumption);
    return{productId:p.id,unit:p.unit,production,inventory:round(production*.16),intermediateConsumption,householdConsumption,publicConsumption,exports:round(Math.max(0,production-demand)*.72),imports:round(Math.max(0,demand-production)*.88),nationalPrice:100,internationalPrice:100,deficitSurplus:round(production-demand),supply:production,demand,price:100,shortage:round(clamp((demand-production)/Math.max(.01,demand)*100,0,100)),trend:0};
  }
  const bank=(c,i)=>{const assets=round(c.economy.gdp*(.23-i*.025));return{id:`${c.id}-bank-${i+1}`,name:`${c.name} Banco ${i+1}`,assets,deposits:round(assets*.67),mortgages:round(assets*.25),businessCredit:round(assets*.24),consumerCredit:round(assets*.12),sovereignBonds:round(assets*.14),nonPerformingLoans:round(clamp(c.economy.unemployment/3,1,18)),regulatoryCapital:12,liquidity:27,sectorExposure:{housing:25,industry:22,services:30,public:14},internationalExposure:round(8+i*5),status:"operating"}};
