      a.privateConsumption=round(a.realGDP*.58*(1-e.inflation/500));a.publicExpenditure=round(a.realGDP*.2);a.grossCapitalFormation=round(a.realGDP*clamp(.18+c.economy.confidence/1000-c.v5.economy.centralBank.policyRate/1000,.1,.34));a.exports=round(Object.values(m).reduce((s,p)=>s+p.exports,0));a.imports=round(Object.values(m).reduce((s,p)=>s+p.imports,0));a.netExports=round(a.exports-a.imports);a.gdpExpenditure=round(a.privateConsumption+a.publicExpenditure+a.grossCapitalFormation+a.netExports);const sectorTotal=Object.values(a.gdpBySector).reduce((s,v)=>s+v,0)||1;for(const k of Object.keys(a.gdpBySector))a.gdpBySector[k]=round(a.realGDP*a.gdpBySector[k]/sectorTotal);a.grossNationalIncome=round(a.realGDP+(a.remittancesReceived-a.remittancesSent)+(a.internationalInvestmentPosition*.015));a.householdDisposableIncome=round(a.privateConsumption+a.nationalSaving*.45);a.nationalSaving=round(Math.max(0,a.grossNationalIncome-a.privateConsumption-a.publicExpenditure));a.formalEconomy=round(a.realGDP*(1-c.v5.economy.informalShare/100));a.informalEconomy=round(a.realGDP-a.formalEconomy);a.foreignExchangeReserves=c.v5.economy.currency.reserves;a.currentAccount=round(a.netExports+a.remittancesReceived-a.remittancesSent);a.capitalAccount=round(a.realGDP*.002);a.financialAccount=round(-a.currentAccount-a.capitalAccount);a.totalFactorProductivity=round(clamp(a.totalFactorProductivity+(c.systems.technology-50)/1000,10,160));
      const b=c.v5.economy.banking,output=a.outputGap,growth=e.growth,debt=e.debtRatio;let phase=growth>4&&e.inflation>5?"overheating":growth>2.2&&b.stress<45?"expansion":growth<-.8&&growth>-4?"recession":growth<=-4?"depression":Math.abs(growth)<.5?"stagnation":output<0&&growth>0?"recovery":b.stress>75?"banking_crisis":debt>140&&c.v5.economy.markets.riskPremium>7?"sovereign_debt_crisis":c.v5.economy.markets.equityIndex>190?"financial_bubble":"expansion";c.v5.economy.cycle.phase=phase;c.v51.expectations.growthNextYear=round(growth*.65+(c.economy.confidence-50)/12);c.v51.expectations.inflationNextYear=round(e.inflation*.72+(c.v5.economy.centralBank.inflationTarget)*.28);factor(c,"inflation","Componentes emergentes",e.inflation,`Alimentos ${i.food}% · energía ${i.energy}% · vivienda ${i.housing}%`);
