  const power=f=>{const p=f.properties,supply=(p.ammunition+p.fuel+p.logistics+p.maintenance)/400;return p.personnel*(p.equipment/100)*(p.readiness/100)*(p.morale+p.cohesion+p.training+p.command+p.intelligence)/500*supply*(1-p.fatigue/140)};
  const findCountry=(s,id)=>s.countries.find(c=>c.id===id);
  const eventExists=(s,type,id)=>(s.v52.causalEvents||[]).some(e=>e.type===type&&e.countryId===id&&s.dayIndex-e.day<120&&e.status!=="resolved");
  function impact(c,key,label,value,reason){c.v5.factors[key]||=[];c.v5.factors[key].push({label,impact:round(value,3),detail:reason});if(c.v5.factors[key].length>20)c.v5.factors[key].shift()}

  V.registerSystem({id:"v52.military.capability-logistics",order:89,frequency:"daily",run:({state,rng})=>{
    for(const c of sovereign(state)){const mil=c.v52.military,s=mil.supply,markets=c.v5.economy.products,war=activeWars(state,c.id).length>0,rand=rng(`v52-military:${c.id}`);s.dailyDemand=Object.fromEntries(X.supplyTypes.map(k=>[k,round(mil.formations.reduce((a,f)=>a+(f.dailyConsumption[k]||0)*(war?1.8:1),0),4)]));const replenishment={fuel:(markets.oil.inventory+markets.gas.inventory)*.003,ammunition:markets.defense.inventory*.008,food:(markets.grains.inventory+markets.meat.inventory)*.003,spareParts:(markets.machinery.inventory+markets.vehicles.inventory)*.003,replacements:c.v51.labor.professions.militaryOfficers.workers*.04,transportCapacity:c.systems.logistics*.015};
      for(const type of X.supplyTypes){const demand=s.dailyDemand[type],available=s.stocks[type],delivered=round(clamp((available+replenishment[type])/Math.max(.001,demand*10)*100,0,100));s.delivered[type]=delivered;s.stocks[type]=round(clamp(available-demand*.18+replenishment[type],0,100))}s.throughput=round(clamp(c.systems.logistics-(activeWars(state,c.id).length*8)+(markets.transport.shortage?-markets.transport.shortage*.2:0),5,100));
      for(const f of mil.formations){const p=f.properties,delivery=avg(X.supplyTypes.map(k=>s.delivered[k]));p.fuel=round(clamp(p.fuel-f.dailyConsumption.fuel*.12+s.delivered.fuel*.008,0,100));p.ammunition=round(clamp(p.ammunition-f.dailyConsumption.ammunition*.15+s.delivered.ammunition*.008,0,100));p.logistics=round(clamp(delivery*.65+s.throughput*.35,0,100));p.fatigue=round(clamp(p.fatigue+(war?1.1:.15)-(war?0:.45),0,100));p.maintenance=round(clamp(p.maintenance-(100-p.logistics)*.012-p.fatigue*.004+s.delivered.spareParts*.006,0,100));p.morale=round(clamp(p.morale+(p.logistics-55)*.006-p.fatigue*.008+(rand()-.5)*.18,0,100));p.cohesion=round(clamp(p.cohesion+(p.command-50)*.004-p.fatigue*.006,0,100));p.readiness=round(clamp((p.equipment+p.morale+p.cohesion+p.training+p.maintenance+p.logistics)/6,0,100));f.mobility=round(clamp(p.fuel*.45+p.maintenance*.25+p.logistics*.3,0,100));f.fireRate=round(clamp(p.ammunition*.5+p.training*.2+p.command*.15+p.intelligence*.15,0,100));f.supplyStatus=delivery<25?"isolated":delivery<55?"undersupplied":"supplied";f.status=p.morale<15||p.cohesion<12?"surrendering":p.fatigue>85?"exhausted":f.supplyStatus==="isolated"?"immobile":"ready"}
      for(const domain of ["ground","air","naval"]){const fs=mil.formations.filter(f=>f.domain===domain);mil.operationalCapacity[domain]=round(fs.reduce((a,f)=>a+power(f),0)/Math.max(1,fs.reduce((a,f)=>a+f.properties.personnel,0))*100)}impact(c,"growth","Consumo militar",-activeWars(state,c.id).length*.08,`${mil.formations.length} formaciones · suministro ${round(avg(Object.values(s.delivered)))}%`)
    }
  }});

  V.registerSystem({id:"v52.war.multidomain-operations",order:91,frequency:"daily",run:({state,rng})=>{
    for(const w of (state.wars||[]).filter(x=>!x.ended)){const a=findCountry(state,w.attackerId||w.attacker),d=findCountry(state,w.defenderId||w.defender);if(!a||!d)continue;const rand=rng(`v52-war:${w.id}`),af=a.v52.military.formations,df=d.v52.military.formations,ap=a.v52.military.operationalCapacity,dp=d.v52.military.operationalCapacity;w.v52={day:0,tempo:"balanced",objective:"degrade_and_control",ground:{},air:{},naval:{},engagements:[],supplyCorridors:[],civilianDamage:0,...w.v52};w.v52.engagements||=[];w.v52.day=(Number(w.v52.day)||0)+1;
      const terrain=round(35+rand()*55),weather=round(25+rand()*65),hour=Math.floor(rand()*24),urban=round(rand()*75),river=rand()<.22?55:5,mines=round(d.v52.military.command.ground.mines),fort=round(d.v52.military.command.ground.fortifications),los=round(clamp(100-terrain*.35-weather*.2-urban*.25,5,100));w.v52.ground={lineOfSight:los,terrain,weather,hour,urbanDensity:urban,riverCrossings:river,mines,fortifications:fort,artillery:a.v52.military.command.ground.artillery,electronicWarfare:a.v52.military.command.ground.electronicWarfare,drones:a.v52.military.command.ground.drones,airSupport:a.v52.military.command.ground.airSupport,reserves:a.v52.military.command.ground.reserves,retreat:dp.ground<ap.ground*.45,encirclement:ap.ground>dp.ground*1.8&&los>45,surrender:dp.ground<18,guerrilla:d.v52.military.command.ground.guerrilla};
      const airA=avg(Object.values(a.v52.military.command.air).map(x=>x.capability+(x.active?12:0))),airD=avg(Object.values(d.v52.military.command.air).map(x=>x.capability+(x.active?12:0))),navA=avg(Object.values(a.v52.military.command.naval).map(x=>x.capability+(x.active?12:0))),navD=avg(Object.values(d.v52.military.command.naval).map(x=>x.capability+(x.active?12:0)));w.v52.air={attacker:round((ap.air+airA)/2),defender:round((dp.air+airD)/2),sorties:round(af.filter(x=>x.domain==="air").length*(2+rand()*5)),aircraftAvailability:round(avg(af.filter(x=>x.domain==="air").map(x=>x.properties.maintenance)))};w.v52.naval={attacker:round((ap.naval+navA)/2),defender:round((dp.naval+navD)/2),detection:round(a.v52.military.command.naval.detection.capability),convoyProtection:round(a.v52.military.command.naval.tradeProtection.capability),blockade:a.v52.military.command.naval.blockades.active};
      const modifiers=(los+weather+(100-urban)+a.v52.military.command.ground.artillery+a.v52.military.command.ground.drones)/500,attack=ap.ground*(.65+modifiers)+(w.v52.air.attacker-w.v52.air.defender)*.2+(rand()-.5)*15,defense=dp.ground*(.8+(fort+mines+urban)/300)+(rand()-.5)*12,delta=round(clamp((attack-defense)/12,-8,8));w.warScore=round(clamp((w.warScore||0)+delta,-100,100));const engagement={id:`op-${w.id}-${state.dayIndex}`,day:state.dayIndex,date:state.date,attack:round(attack),defense:round(defense),result:delta>2?"advance":delta<-2?"repulsed":"stalemate",territoryChange:round(delta*.18),attackerSupply:round(avg(Object.values(a.v52.military.supply.delivered))),defenderSupply:round(avg(Object.values(d.v52.military.supply.delivered))),factors:{...w.v52.ground},air:{...w.v52.air},naval:{...w.v52.naval}};w.v52.engagements.push(engagement);if(w.v52.engagements.length>60)w.v52.engagements.shift();state.v52.operationalBattles.push({...engagement,warId:w.id});if(state.v52.operationalBattles.length>300)state.v52.operationalBattles.shift();for(const f of [...af,...df])if(f.properties)f.properties.fatigue=round(clamp(f.properties.fatigue+Math.abs(delta)*.08,0,100));
    }
  }});

  V.registerSystem({id:"v52.occupation.resistance-postwar",order:93,frequency:"weekly",run:({state,rng})=>{
    for(const zone of state.occupationZones||[]){const occupier=findCountry(state,zone.occupierId),target=findCountry(state,zone.formerOwnerId);if(occupier&&target)X.createPostwarCase(state,(state.wars||[]).find(w=>w.id===zone.warId),occupier,target)}for(const p of state.v52.postwarCases){if(p.status==="closed")continue;const occupier=findCountry(state,p.occupierId),target=findCountry(state,p.targetId),r=p.resistance,rand=rng(`v52-occupation:${p.id}`);if(!occupier||!target)continue;const identity=(r.nationalIdentity+r.religiousDifferences)/2,coercion=r.repression-r.counterinsurgency*.45,grievance=r.civilianDamage+r.sabotage+r.terrorism+identity-r.reconstruction-r.refugeeReturn-r.collaboration;r.insurgency=round(clamp(r.insurgency+grievance*.012+coercion*.006+(rand()-.5)*1.4,0,100));r.sabotage=round(clamp(r.sabotage+r.insurgency*.02-r.counterinsurgency*.014-r.collaboration*.006,0,100));r.terrorism=round(clamp(r.terrorism+r.insurgency*.008-r.counterinsurgency*.01,0,100));r.collaboration=round(clamp(r.collaboration+r.occupierLegitimacy*.008+r.reconstruction*.01-r.repression*.012,0,100));r.reconstruction=round(clamp(r.reconstruction+(occupier.budgets.infrastructure||3)*.06-r.sabotage*.008,0,100));r.refugeeReturn=round(clamp(r.refugeeReturn+r.reconstruction*.012-r.insurgency*.01,0,100));r.occupierLegitimacy=round(clamp(r.occupierLegitimacy+r.reconstruction*.012+r.collaboration*.008-r.civilianDamage*.008-r.repression*.006,0,100));p.integrationProgress=round(clamp(p.integrationProgress+(r.occupierLegitimacy+r.reconstruction+r.collaboration-r.insurgency-r.sabotage)/(Math.max(15,p.integrationDifficulty)*30),0,100));p.occupationCost=round(target.economy.gdp*(.002+r.insurgency/10000+p.integrationDifficulty/30000));occupier.economy.treasury=round(Math.max(0,occupier.economy.treasury-p.occupationCost/52));if(p.selectedOption==="annexation"&&p.integrationProgress<100){target.v5.integrationPenalty=round(clamp(100-p.integrationProgress,0,100));target.sovereign=false}else if(p.integrationProgress>=100){p.status="integrated";target.v5.integrationPenalty=0}if(p.selectedOption&&["puppetState","alliedGovernment","protectorate","autonomy","supervisedIndependence"].includes(p.selectedOption)){target.sovereign=true;target.vassalOf=occupier.id;target.relations[occupier.id]=85}if(p.selectedOption==="temporaryOccupation"&&state.dayIndex-p.startedDay>365)p.status="closed";
    }
  }});

  V.registerSystem({id:"v52.intelligence.estimation-operations",order:81,frequency:"weekly",run:({state,rng})=>{
    for(const observer of state.countries){const intel=observer.v52.intelligence;for(const dossier of Object.values(intel.dossiers)){const target=findCountry(state,dossier.targetId);if(!target)continue;const source=dossier.sources[0]||"press",quality=(intel.sources[source]?.coverage+intel.sources[source]?.reliability)/2;const real={gdp:target.economy.gdp,population:target.economy.population,militaryCapacity:target.systems.military,readiness:target.militaryReadiness||target.systems.military,technology:target.systems.technology,reserves:target.v5.economy.currency.reserves};for(const [key,datum] of Object.entries(dossier.metrics)){datum.ageDays+=7;const uncertainty=clamp(40-quality*.34+datum.ageDays*.04,3,45),bias=(dossier.deceptionRisk/100)*(V.random(state,`intel-bias:${observer.id}:${target.id}:${key}`)()-.3);datum.estimate=round(datum.estimate*.72+real[key]*.28*(1+bias*.15));datum.realValue=real[key];datum.confidenceInterval=[round(datum.estimate*(1-uncertainty/100)),round(datum.estimate*(1+uncertainty/100))];datum.confidence=round(100-uncertainty);datum.possibleDisinformation=dossier.deceptionRisk>datum.confidence;datum.source=source;if(quality>68){datum.ageDays=0;datum.observedDay=state.dayIndex}}dossier.lastUpdated=state.dayIndex;intel.estimatesUpdated++}
      for(const op of intel.operations.filter(x=>x.status==="active")){const target=findCountry(state,op.targetId),rand=rng(`intel-op:${op.id}`);op.progress=round(clamp(op.progress+(op.resources+intel.counterintelligence/4-(target?.v52.intelligence.counterintelligence||50)/5)/12+rand()*3,0,100));op.detectionRisk=round(clamp(op.detectionRisk+(target?.v52.intelligence.counterintelligence||50)*.015-op.covertness*.01,0,100));if(op.progress>=100){op.status="completed";op.completedDay=state.dayIndex;if(target){if(op.type==="technologyTheft"){const tech=Object.values(target.v52.technology.knowledge).sort((a,b)=>b.level-a.level)[0],own=observer.v52.technology.knowledge[tech.id];own.level=round(clamp(own.level+8,0,140));own.status="stolen"}if(op.type==="sabotage")target.systems.industry=round(clamp(target.systems.industry-3,0,100));if(op.type==="cyberAttack")target.systems.intelligence=round(clamp(target.systems.intelligence-4,0,100));if(op.type==="disinformation")target.v51.media.disinformation=round(clamp(target.v51.media.disinformation+12,0,100));if(op.type==="coup")target.v51.government.confidence=round(clamp(target.v51.government.confidence-18,0,100));if(op.type==="electoralInterference")target.v51.media.polarization=round(clamp(target.v51.media.polarization+9,0,100))}}}
    }
  }});

  V.registerSystem({id:"v52.technology.knowledge-diffusion",order:85,frequency:"monthly",run:({state})=>{
    for(const c of sovereign(state)){const t=c.v52.technology,portfolio=t.portfolio;portfolio.basicResearch=round(clamp(portfolio.basicResearch+(c.budgets.research-2)*.08,0,120));portfolio.appliedResearch=round(clamp(portfolio.appliedResearch+(c.v5.economy.firms.reduce((s,f)=>s+f.investment,0)/Math.max(1,c.economy.gdp))*2,0,120));portfolio.patents=round(clamp(portfolio.patents+c.v5.economy.firms.reduce((s,f)=>s+f.patents,0)/10000,0,140));portfolio.humanCapital=round(clamp(portfolio.humanCapital+c.v51.labor.professions.researchers.workers/Math.max(.01,c.economy.population)*.4,0,120));portfolio.equipment=round(clamp((c.systems.industry+c.v5.economy.products.machinery.production/Math.max(.01,c.v5.economy.products.machinery.demand)*50)/2,0,120));portfolio.internationalCooperation=round(clamp(c.v5.foreign.treatyCompliance,0,100));portfolio.companies=round(clamp(avg(c.v5.economy.firms.map(f=>f.productivity)),0,120));portfolio.universities=round(clamp(c.v5.society.education.quality,0,100));portfolio.espionage=round(clamp(c.v52.intelligence.operations.filter(x=>x.status==="completed").length*3+c.systems.intelligence*.4,0,100));portfolio.supplyChain=round(clamp(100-avg(Object.values(c.v5.economy.products).map(p=>p.shortage)),0,100));const capacity=avg(Object.values(portfolio));t.innovationRate=round(capacity/9);t.diffusionRate=round(clamp((portfolio.internationalCooperation+portfolio.companies+portfolio.universities)/3,0,100));for(const k of Object.values(t.knowledge)){const dep=avg(Object.values(k.dependencies)),embargo=k.diffusion.embargoedBy.length?-.6:0,license=k.diffusion.mode==="licensed"?.7:0,spy=k.status==="stolen"?.5:0;k.progress=round(clamp(k.progress+(capacity+dep)/220+license+spy+embargo,0,100));if(k.progress>=100&&k.status!=="invented"){k.status="invented";k.diffusion.mode="patented";k.patentOwner=c.id;k.history.push({day:state.dayIndex,type:"invented"})}if(k.status==="invented"||k.status==="diffusing")k.level=round(clamp(k.level+t.diffusionRate/1200,0,150));}c.systems.technology=round(clamp(c.systems.technology*.88+capacity*.12,0,140));
    }
  }});

  V.registerSystem({id:"v52.climate.resources-causal-chain",order:62,frequency:"weekly",run:({state,rng})=>{
    for(const c of sovereign(state)){const cl=c.v52.climate,m=cl.metrics,rand=rng(`v52-climate:${c.id}`),warming=state.v5Networks.climate.globalTemperature||1.5;m.temperature=round(m.temperature+warming*.002+(rand()-.5)*.03);m.precipitation=round(clamp(m.precipitation*(1+(rand()-.5)*.008),20,4000));m.drought=round(clamp(m.drought+(m.temperature-18)*.012+(700-m.precipitation)*.0008-m.waterAvailability*.006,0,100));m.flooding=round(clamp(m.flooding+(m.precipitation-900)*.001+m.seaLevel*.02-c.v5.infrastructure.climate.adaptation*.006,0,100));m.wildfires=round(clamp(m.wildfires+m.drought*.012+m.temperature*.018-c.v5.infrastructure.climate.adaptation*.006,0,100));m.hurricanes=round(clamp(m.hurricanes+(m.temperature-20)*.006+(rand()-.5)*.4,0,100));m.desertification=round(clamp(m.desertification+m.drought*.008-m.precipitation*.0002,0,100));m.seaLevel=round(m.seaLevel+warming*.0007,4);m.airQuality=round(clamp(m.airQuality-c.v5.infrastructure.climate.emissions/Math.max(1,c.economy.gdp)*.08+(c.systems.renewables||20)*.002,0,100));m.waterAvailability=round(clamp(m.waterAvailability-m.drought*.008-m.desertification*.003+(c.budgets.infrastructure||3)*.012,0,100));m.soilFertility=round(clamp(m.soilFertility-m.drought*.006-m.flooding*.004+(c.systems.food-50)*.003,0,100));m.biodiversityLoss=round(clamp(m.biodiversityLoss+m.desertification*.004+m.wildfires*.004-(c.systems.renewables||20)*.001,0,100));const agricultureLoss=(m.drought+m.flooding+m.wildfires+(100-m.soilFertility))/500;c.v5.economy.products.grains.production=round(Math.max(.001,c.v5.economy.products.grains.production*(1-agricultureLoss/52)));c.v51.inflation.food=round(clamp(c.v51.inflation.food+agricultureLoss*.18,0,80));c.v5.society.opinion.protestPotential=round(clamp(c.v5.society.opinion.protestPotential+c.v51.inflation.food*.002,0,100));c.v51.demography.migration.drivers.climate=round(clamp(100-(m.drought+m.flooding+(100-m.waterAvailability))/3,0,100));cl.causalImpacts=[{from:"drought",to:"agriculture",impact:round(-agricultureLoss*100)},{from:"agriculture",to:"foodInflation",impact:round(agricultureLoss*18)},{from:"foodInflation",to:"protests",impact:round(c.v51.inflation.food*.02)},{from:"waterAvailability",to:"migration",impact:round((100-m.waterAvailability)*.08)}];if((m.hurricanes>70||m.flooding>80||m.wildfires>82)&&!cl.disasters.some(x=>state.dayIndex-x.day<60)){const type=m.hurricanes>70?"hurricane":m.flooding>80?"flood":"wildfire",damage=round(c.economy.gdp*(.002+rand()*.012));cl.disasters.push({id:`climate-${c.id}-${state.dayIndex}`,day:state.dayIndex,type,damage,logisticsDamage:round(damage*.35),fiscalCost:round(damage*.55)});c.systems.logistics=round(clamp(c.systems.logistics-damage/Math.max(1,c.economy.gdp)*160,0,100));c.economy.debtRatio=round(c.economy.debtRatio+damage/c.economy.gdp*55)}impact(c,"inflation","Cadena climática",agricultureLoss*.18,`Sequía ${m.drought}% → agricultura → alimentos`)
    }
  }});

  V.registerSystem({id:"v52.events.condition-generated",order:97,frequency:"weekly",run:({state})=>{
    for(const c of sovereign(state)){const p=c.v5.economy.products,m=c.v52.climate,conditions=[
      {type:"energy_crisis",score:p.gas.shortage*.45+(100-Math.min(100,p.gas.inventory/Math.max(.01,p.gas.demand)*100))*.3+Math.max(0,12-m.metrics.temperature)*2,title:`Crisis energética en ${c.name}`,causes:[`Déficit de gas ${round(p.gas.shortage)}%`,`Reservas ${round(p.gas.inventory)} ${p.gas.unit}`,`Temperatura ${m.metrics.temperature} °C`],effects:["precio energético","transporte","inflación"],options:["Racionamiento escalonado","Compra de emergencia","Subsidio focalizado"]},
      {type:"mass_protests",score:c.economy.unemployment*.7+c.v51.crime.politicalCorruption*.35+c.v51.inflation.food*.9+(100-c.systems.approval)*.35,title:`Protestas masivas en ${c.name}`,causes:[`Desempleo ${c.economy.unemployment}%`,`Corrupción ${c.v51.crime.politicalCorruption}%`,`Inflación alimentaria ${c.v51.inflation.food}%`],effects:["protesta","estabilidad","gobierno"],options:["Diálogo y reformas","Paquete social","Orden público proporcional"]},
      {type:"banking_crisis",score:Math.max(0,c.v5.society.housing.priceIndex-135)*.35+c.v5.economy.centralBank.policyRate*2+avg(c.v5.economy.banks.map(b=>b.mortgages/b.assets*100+b.nonPerformingLoans))*.7,title:`Crisis bancaria en ${c.name}`,causes:[`Vivienda ${c.v5.society.housing.priceIndex}`,`Tipos ${c.v5.economy.centralBank.policyRate}%`,`Exposición hipotecaria elevada`],effects:["mora","crédito","inversión"],options:["Resolución bancaria","Recapitalización","Garantía de depósitos"]},
      {type:"coup_risk",score:(100-c.v51.government.confidence)*.45+(100-c.government.legitimacy)*.35+(100-c.v52.military.formations[0].properties.morale)*.25,title:`Riesgo de golpe en ${c.name}`,causes:[`Confianza gubernamental ${c.v51.government.confidence}%`,`Legitimidad ${c.government.legitimacy}%`,`Moral militar ${c.v52.military.formations[0].properties.morale}%`],effects:["lealtad militar","gobierno","estabilidad"],options:["Reforma de mando","Pacto institucional","Alerta de inteligencia"]}
    ];const trigger=conditions.sort((a,b)=>b.score-a.score)[0];if(trigger.score>68&&!eventExists(state,trigger.type,c.id)){const ev={id:`causal-${trigger.type}-${c.id}-${state.dayIndex}`,countryId:c.id,day:state.dayIndex,date:state.date,status:"active",severity:round(clamp(trigger.score,0,100)),explanation:`${trigger.causes.join(" → ")} → ${trigger.effects.join(" → ")}.`,tree:trigger.causes.map((cause,i)=>({id:`cause-${i}`,label:cause,impact:round(trigger.score/(i+2)),children:[]})),...trigger};state.v52.causalEvents.push(ev);state.actionInbox.push({id:`decision-${ev.id}`,type:"causal",eventId:ev.id,countryId:c.id,title:ev.title,text:`Causas: ${ev.causes.join(" · ")}`,options:ev.options,status:"pending"})}}
    if(state.v52.causalEvents.length>300)state.v52.causalEvents.splice(0,state.v52.causalEvents.length-300);
  }});

  function flatten(value,prefix="",out={},depth=0){if(depth>5||Object.keys(out).length>700)return out;for(const [k,v] of Object.entries(value||{})){const key=prefix?`${prefix}.${k}`:k;if(typeof v==="number"&&Number.isFinite(v))out[key]=v;else if(v&&typeof v==="object"&&!Array.isArray(v))flatten(v,key,out,depth+1)}return out}
  V.registerSystem({id:"v52.analytics.history-risks-reports",order:99,frequency:"daily",run:({state})=>{const c=findCountry(state,state.controlledCountryId)||sovereign(state)[0],a=c.v52.analysis,metrics=flatten({economy:c.economy,systems:c.systems,v5:c.v5,v51:c.v51,v52:{military:c.v52.military.operationalCapacity,climate:c.v52.climate.metrics,technology:c.v52.technology.portfolio}});for(const [key,value] of Object.entries(metrics)){a.metricHistory[key]||=[];a.metricHistory[key].push({day:state.dayIndex,date:state.date,value:round(value,4)});if(a.metricHistory[key].length>730)a.metricHistory[key].shift()}a.explanations.inflation=[{label:"Energía",impact:round(c.v51.inflation.energy*.28)},{label:"Alimentos",impact:round(c.v51.inflation.food*.2)},{label:"Salarios",impact:round(c.v51.inflation.wage*.18)},{label:"Moneda",impact:round(c.v51.inflation.imported*.16)},{label:"Subsidios",impact:round(-(c.v5.infrastructure.energy.market.subsidies||0)*.06)}];const baseRisks=[{id:"energy",label:"Crisis energética",score:round(c.v5.economy.products.gas.shortage*.7+c.v5.infrastructure.energy.blackoutRisk*.3)},{id:"banking",label:"Crisis bancaria",score:round(c.v5.economy.banking.stress)},{id:"social",label:"Protesta social",score:round(c.v5.society.opinion.protestPotential)},{id:"war",label:"Escalada militar",score:round(state.worldIndex.warRisk)},{id:"climate",label:"Impacto climático",score:round(avg([c.v52.climate.metrics.drought,c.v52.climate.metrics.flooding,c.v52.climate.metrics.wildfires]))},{id:"occupation",label:"Insurgencia",score:round(Math.max(0,...state.v52.postwarCases.filter(x=>x.occupierId===c.id).map(x=>x.resistance.insurgency)))}];for(const h of X.riskHorizons)a.risks[h]=baseRisks.map(r=>({...r,horizon:h,probability:round(clamp(r.score*(h===30?.65:h===90?.85:1.05),0,100)),impact:round(clamp(r.score*(h===365?1.1:1),0,100))})).sort((x,y)=>y.probability-x.probability);const maps=state.v52.analysisMaps,mk=(id,nodes,edges)=>{maps[id]={id,nodes:nodes.slice(0,120),edges:edges.slice(0,300),updatedDay:state.dayIndex}};mk("tradeFlows",sovereign(state).map(x=>({id:x.id,label:x.name,value:x.economy.tradeBalance})),(state.v51.logistics.routes||[]).map(x=>({from:x.from,to:x.to,value:x.capacity,product:x.productId})));mk("electricGrid",sovereign(state).map(x=>({id:x.id,label:x.name,value:x.v5.infrastructure.energy.availableGeneration||0})),state.v5Networks.energy.interconnectors||[]);mk("logistics",state.v51.logistics.nodes.map(x=>({id:x.id,label:x.name,value:x.capacity})),state.v51.logistics.routes.map(x=>({from:x.from,to:x.to,value:x.capacity})));mk("migration",sovereign(state).map(x=>({id:x.id,label:x.name,value:x.v51.demography.migration.flows.refugees})),sovereign(state).slice(1).map((x,i)=>({from:x.id,to:sovereign(state)[i%sovereign(state).length].id,value:x.v51.demography.migration.flows.seasonal})));mk("industrialChains",c.v5.economy.firms.map(f=>({id:f.id,label:f.name,value:f.revenue})),c.v5.economy.firms.flatMap(f=>f.suppliers.map(s=>({from:s,to:f.id,value:f.revenue*.1}))));mk("influence",sovereign(state).map(x=>({id:x.id,label:x.name,value:x.v5.foreign.influence})),Object.entries(c.v51.diplomacy.relations).map(([id,r])=>({from:c.id,to:id,value:r.culturalInfluence})));mk("intelligence",Object.values(c.v52.intelligence.dossiers).map(x=>({id:x.targetId,label:x.targetId,value:avg(Object.values(x.metrics).map(m=>m.confidence))})),c.v52.intelligence.operations.map(x=>({from:c.id,to:x.targetId,value:x.progress})));mk("pollution",sovereign(state).map(x=>({id:x.id,label:x.name,value:100-x.v52.climate.metrics.airQuality})),[]);mk("politicalOpinion",sovereign(state).map(x=>({id:x.id,label:x.name,value:x.systems.approval})),[]);if(state.dayIndex%7===0)a.reports.push({id:`weekly-${state.dayIndex}`,type:"weekly",day:state.dayIndex,title:`Informe semanal · ${c.name}`,summary:`${c.economy.growth}% crecimiento, ${c.economy.inflation}% inflación, riesgo principal ${a.risks[30][0].label}.`,risks:a.risks[30].slice(0,5)});if(state.dayIndex%30===0)a.reports.push({id:`monthly-${state.dayIndex}`,type:"monthly",day:state.dayIndex,title:"Informe mensual",summary:`Ciclo ${c.v5.economy.cycle.phase}; banca ${c.v5.economy.banking.stress}; aprobación ${c.systems.approval}.`,risks:a.risks[90].slice(0,5)});if(state.dayIndex%365===0)a.reports.push({id:`annual-${state.dayIndex}`,type:"annual",day:state.dayIndex,title:"Informe anual",summary:`PIB ${c.economy.gdp}; deuda ${c.economy.debtRatio}; tecnología ${c.systems.technology}.`,risks:a.risks[365].slice(0,5)});if(state.dayIndex%7===0)a.reports.push({id:`cabinet-${state.dayIndex}`,type:"cabinet",day:state.dayIndex,title:"Situación de gabinete",summary:`Decisiones pendientes ${(state.actionInbox||[]).filter(x=>x.status==="pending").length}; guerras ${activeWars(state,c.id).length}.`,risks:a.risks[30].slice(0,3)});if(a.reports.length>100)a.reports.splice(0,a.reports.length-100);a.journal.push({day:state.dayIndex,date:state.date,headline:`${c.v5.economy.cycle.phase} · ${a.risks[30][0].label} ${a.risks[30][0].probability}%`,events:state.v52.causalEvents.filter(x=>x.day===state.dayIndex).map(x=>x.title),wars:activeWars(state,c.id).map(x=>x.id)});if(a.journal.length>1000)a.journal.shift();
  }});
